mapper.insert:

    SELECT
        'RESM'||
        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(RESUME_NO), LENGTH('RESM' ) + 1)), 0) + 1, 6, '0')
    FROM RESUME

INSERT INTO RESUME (
	RESUME_NO
	, USER_ID
	, USER_NAME
	, PHOTO
	, BIRTH
	, EMAIL
	, TEL
	, ADDRESS
	, VETERAN_REASON
	, UPDATE_DATE
	, RESUME_SUBMIT_YN
	, RESUME_DELETE_YN
) VALUES (
	#{resumeNo}
	, #{userId}
	, #{userName}
	, #{photo}
	, REPLACE(#{birth}, '-', '')
	, #{email}
	, #{tel}
	, #{address}
	, #{veteranReason}
	, TO_CHAR(SYSDATE, 'YYYYMMDD')
	, #{resumeSubmitYn}
	, #{resumeDeleteYn}
)

mapper.update:
UPDATE RESUME 
   SET USER_ID = #{userId}
       , USER_NAME = #{userName}
       , PHOTO = #{photo}
       , BIRTH = REPLACE(#{birth}, '-', '')
       , EMAIL = #{email}
       , TEL = #{tel}
       , ADDRESS = #{address}
       , VETERAN_REASON = #{veteranReason}
       , UPDATE_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD')
       , RESUME_SUBMIT_YN = #{resumeSubmitYn}
       , RESUME_DELETE_YN = #{resumeDeleteYn}
 WHERE RESUME_NO = #{resumeNo}
